code.cpp:
class Solution {
public:
    bool checkIfExist(vector<int>& arr) {
        bool seen[4001] = {false};
        for (int x : arr) {
            if (seen[2 * x + 2000]) return true;
            if (x % 2 == 0 && seen[x / 2 + 2000]) return true;
            seen[x + 2000] = true;
        }
        return false;
    }
};
